/** Private Git fixtures only; no application execution, database, build or release authority. */
import test from'node:test';import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{mkdtempSync,writeFileSync,mkdirSync,symlinkSync,rmSync}from'node:fs';import{tmpdir}from'node:os';import{join}from'node:path';import{createCommittedSourceReader}from'../../../scripts/improve/committed-source-blobs.ts';
function fixture(t){const root=mkdtempSync(join(tmpdir(),'source-batch-'));t.after(()=>rmSync(root,{recursive:true,force:true}));const git=(...args)=>execFileSync('git',['-C',root,...args],{encoding:'utf8'}).trim();git('init','-q');git('config','user.name','Fictional Source');git('config','user.email','fictional@example.invalid');mkdirSync(join(root,'app'));writeFileSync(join(root,'app','binary.ts'),Buffer.from([0,10,255,13,0]));writeFileSync(join(root,'app','same.ts'),'same');writeFileSync(join(root,'app','alias.ts'),'same');writeFileSync(join(root,'app','empty.ts'),'');writeFileSync(join(root,'app','space [page].ts'),'special path');symlinkSync('same.ts',join(root,'app','link.ts'));git('add','.');git('commit','-qm','private immutable source fixture');return{root,git,candidate:git('rev-parse','HEAD')};}
test('matches real immutable git bytes, binary data, aliases, empty file and special paths',t=>{const f=fixture(t),paths=['app/binary.ts','app/same.ts','app/alias.ts','app/empty.ts','app/space [page].ts'];const result=createCommittedSourceReader(f.root,f.candidate).read(paths);for(const path of paths)assert.deepEqual(result.get(path),execFileSync('git',['-C',f.root,'show',f.candidate+':'+path]));assert.equal(result.size,paths.length);});
test('reads selected immutable commit even if working bytes change',t=>{const f=fixture(t);writeFileSync(join(f.root,'app/same.ts'),'changed after commit');assert.equal(createCommittedSourceReader(f.root,f.candidate).read(['app/same.ts']).get('app/same.ts').toString(),'same');});
test('refuses selected symlink without following its valid target',t=>{const f=fixture(t);assert.throws(()=>createCommittedSourceReader(f.root,f.candidate).read(['app/link.ts']),/regular file/);});
for(const paths of [['app/missing.ts'],['app'],['app/same.ts','app/same.ts'],['../app/same.ts'],['/app/same.ts'],['app/./same.ts'],[],['app/same.ts\nHEAD']])test('refuses invalid selection '+JSON.stringify(paths),t=>{const f=fixture(t);assert.throws(()=>createCommittedSourceReader(f.root,f.candidate).read(paths));});
test('refuses object exceeding declared size before byte transfer',t=>{const f=fixture(t);assert.throws(()=>createCommittedSourceReader(f.root,f.candidate).read(['app/same.ts'],3),/bound/);});
test('refuses invalid ref, absent commit and unsafe bound',t=>{const f=fixture(t);assert.throws(()=>createCommittedSourceReader(f.root,'HEAD'));assert.throws(()=>createCommittedSourceReader(f.root,'a'.repeat(40)));assert.throws(()=>createCommittedSourceReader(f.root,f.candidate).read(['app/same.ts'],0));});
